export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

// "1:42 PM" — hour without leading zero, two-digit minutes, uppercase AM/PM.
export function formatTime(date) {
  let hours = date.getHours()
  const minutes = date.getMinutes()
  const suffix = hours >= 12 ? "PM" : "AM"
  hours = hours % 12
  if (hours === 0) hours = 12
  return `${hours}:${String(minutes).padStart(2, "0")} ${suffix}`
}

const MONTHS_SHORT = [ "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec" ]
const MONTHS_LONG = [ "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" ]
const WEEKDAYS_LONG = [ "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" ]

// "Sep 12", or "Sep 12, 2024" when the year differs from the reference.
export function formatShortDate(date, now = new Date()) {
  const month = MONTHS_SHORT[date.getMonth()]
  const day = date.getDate()
  if (date.getFullYear() === now.getFullYear()) {
    return `${month} ${day}`
  } else {
    return `${month} ${day}, ${date.getFullYear()}`
  }
}

// "Sep 12, 2025" — always with year.
export function formatShortDateWithYear(date) {
  const month = MONTHS_SHORT[date.getMonth()]
  const day = date.getDate()
  return `${month} ${day}, ${date.getFullYear()}`
}

// "Monday, September 1"
export function formatWeekdayDate(date) {
  const weekday = WEEKDAYS_LONG[date.getDay()]
  const month = MONTHS_LONG[date.getMonth()]
  const day = date.getDate()
  return `${weekday}, ${month} ${day}`
}

// "9/12/25, 1:42 PM" — matches Ruby "%-m/%-d/%y, %l:%M %p".
export function formatDayTime(date) {
  const month = date.getMonth() + 1
  const day = date.getDate()
  const year = String(date.getFullYear()).slice(-2)
  return `${month}/${day}/${year}, ${formatTime(date)}`
}

// Full local date for tooltips, e.g. "Monday, September 1, 2025 at 1:42 PM".
export function formatFull(date) {
  return `${formatWeekdayDate(date)}, ${date.getFullYear()} at ${formatTime(date)}`
}

// Relative day words in the viewer's own timezone.
