// Same day          -> "1:42 PM"
// Yesterday         -> "yesterday"
// Tomorrow          -> "tomorrow"
// Within the week   -> "5 days ago" / "in 3 days"
// Further out       -> "Sep 12" (with year when different)
export function formatRelative(date, now = new Date()) {
  const diff = signedDifferenceInDays(now, date)

  if (diff === 0) {
    return formatTime(date)
  } else if (diff === -1) {
    return "yesterday"
  } else if (diff === 1) {
    return "tomorrow"
  } else if (diff < -1 && diff >= -6) {
    return `${-diff} days ago`
  } else if (diff > 1 && diff <= 6) {
    return `in ${diff} days`
  } else {
    return formatShortDate(date, now)
  }
